    if (rc != NGX_OK) {
        ngx_log_error(NGX_LOG_ERR, r->connection->log, 0,
                      "handler::shm_add_cache() failed");
    }
#endif

    return NGX_DECLINED;
}

ngx_http_vhost_traffic_status_shm_add_server(ngx_http_request_t *r)
{
    unsigned                                   type;
    ngx_int_t                                  rc;
    ngx_str_t                                  key, dst;
    ngx_http_core_srv_conf_t                  *cscf;
    ngx_http_vhost_traffic_status_loc_conf_t  *vtscf;

    vtscf = ngx_http_get_module_loc_conf(r, ngx_http_vhost_traffic_status_module);

    cscf = ngx_http_get_module_srv_conf(r, ngx_http_core_module);

    if (vtscf->filter && vtscf->filter_host && r->headers_in.server.len) {
        /* set the key by host header */
        dst = r->headers_in.server;

    } else {
        /* set the key by server_name variable */
        dst = cscf->server_name;
        if (dst.len == 0) {
            dst.len = 1;
            dst.data = (u_char *) "_";
        }
    }

    type = NGX_HTTP_VHOST_TRAFFIC_STATUS_UPSTREAM_NO;

    rc = ngx_http_vhost_traffic_status_node_generate_key(r->pool, &key, &dst, type);
    if (rc != NGX_OK) {
        return NGX_ERROR;
    }

    return ngx_http_vhost_traffic_status_shm_add_node(r, &key, type, NULL);
}

ngx_int_t
ngx_http_vhost_traffic_status_node_generate_key(ngx_pool_t *pool,
    ngx_str_t *buf, ngx_str_t *dst, unsigned type)
{
    size_t   len;
    u_char  *p;

    len = ngx_strlen(ngx_http_vhost_traffic_status_group_to_string(type));

    buf->len = len + sizeof("@") - 1 + dst->len;
    buf->data = ngx_pcalloc(pool, buf->len);
    if (buf->data == NULL) {
        *buf = *dst;
        return NGX_ERROR;
    }

    p = buf->data;

    p = ngx_cpymem(p, ngx_http_vhost_traffic_status_group_to_string(type), len);
    *p++ = NGX_HTTP_VHOST_TRAFFIC_STATUS_KEY_SEPARATOR;
    p = ngx_cpymem(p, dst->data, dst->len);

    return NGX_OK;
}

    ctx = ngx_http_get_module_main_conf(r, ngx_http_vhost_traffic_status_module);

    vtscf = ngx_http_get_module_loc_conf(r, ngx_http_vhost_traffic_status_module);

    if (key->len == 0) {
        return NGX_ERROR;
    }

    shpool = (ngx_slab_pool_t *) vtscf->shm_zone->shm.addr;


    /* the status of the attempt where there is one, of the request otherwise */
    status = (state != NULL) ? state->status : r->headers_out.status;

    status_code_slot = 0;
    if (ctx->measure_all_status_codes) {
        if (status >= 100 && status < 600) {
            // slot 0 is reserved to other status codes <100 and >=600
            status_code_slot = status - 99;
        }
    } else if (ctx->measure_status_codes != NULL) {
        status_code_slot = ngx_http_vhost_traffic_status_find_status_code_slot(status,
                                                                              ctx->measure_status_codes);
    }

    /* the hash does not touch the shared memory, keep it out of the lock */
    hash = ngx_crc32_short(key->data, key->len);

#if (NGX_HTTP_CACHE)
    cache_max_size = 0;
    cache_used_size = 0;

    /* the sizes come from the zone of the cache, which has a mutex of its own */

    if (type == NGX_HTTP_VHOST_TRAFFIC_STATUS_UPSTREAM_CC) {
        ngx_http_vhost_traffic_status_shm_get_cache_size(r, &cache_max_size,
                                                         &cache_used_size);
    }
#endif

    ngx_shmtx_lock(&shpool->mutex);

    /* find node */
    node = ngx_http_vhost_traffic_status_find_node(r, key, type, hash);

    /* set common */
    if (node == NULL) {
        init = NGX_HTTP_VHOST_TRAFFIC_STATUS_NODE_NONE;

        /* delete lru node */
        lrun = ngx_http_vhost_traffic_status_find_lru(r, type, key);
        if (lrun != NULL) {

            /* while the node is still there to be read */

            ngx_http_vhost_traffic_status_node_filter_account(ctx,
                (ngx_http_vhost_traffic_status_node_t *) &lrun->color, -1);

            ngx_rbtree_delete(ctx->rbtree, lrun);
            ngx_slab_free_locked(shpool, lrun);
        }

        size = offsetof(ngx_rbtree_node_t, color)
               + offsetof(ngx_http_vhost_traffic_status_node_t, data)
               + key->len;

        node = ngx_slab_alloc_locked(shpool, size);
        if (node == NULL) {
            ngx_http_vhost_traffic_status_shm_alloc_failed(r);

            ngx_shmtx_unlock(&shpool->mutex);
            return NGX_ERROR;
        }

        vtsn = (ngx_http_vhost_traffic_status_node_t *) &node->color;

        node->key = hash;
        vtsn->len = key->len;
        vtsn->ignore_status = vtscf->ignore_status;

        if (ctx->measure_status_codes != NULL) {
            vtsn->stat_status_code_counter = ngx_slab_alloc_locked(shpool, sizeof(ngx_atomic_t) * (ctx->measure_status_codes->nelts + 1));
            if (vtsn->stat_status_code_counter == NULL) {
                ngx_http_vhost_traffic_status_shm_alloc_failed(r);

                ngx_slab_free_locked(shpool, node);
                ngx_shmtx_unlock(&shpool->mutex);
                return NGX_ERROR;
            }
            vtsn->stat_status_code_length = ctx->measure_status_codes->nelts;
        }

        ngx_http_vhost_traffic_status_node_init(r, vtsn, status_code_slot, state);

        vtsn->stat_upstream.type = type;
        ngx_memcpy(vtsn->data, key->data, key->len);

        ngx_rbtree_insert(ctx->rbtree, node);

        ngx_http_vhost_traffic_status_node_filter_account(ctx, vtsn, 1);

    } else {
        init = NGX_HTTP_VHOST_TRAFFIC_STATUS_NODE_FIND;
        vtsn = (ngx_http_vhost_traffic_status_node_t *) &node->color;
        ngx_http_vhost_traffic_status_node_set(r, vtsn, status_code_slot, state);
    }

ngx_rbtree_node_t *
ngx_http_vhost_traffic_status_find_node(ngx_http_request_t *r,
    ngx_str_t *key, unsigned type, uint32_t key_hash)
{
    uint32_t                              hash;
    ngx_rbtree_node_t                    *node;
    ngx_http_vhost_traffic_status_ctx_t  *ctx;

    ctx = ngx_http_get_module_main_conf(r, ngx_http_vhost_traffic_status_module);

    hash = key_hash;

    if (hash == 0) {
        hash = ngx_crc32_short(key->data, key->len);
    }

    node = ngx_http_vhost_traffic_status_node_lookup(ctx->rbtree, key, hash);

    return node;
}

ngx_rbtree_node_t *
ngx_http_vhost_traffic_status_find_lru(ngx_http_request_t *r, unsigned type,
    ngx_str_t *key)
{
    ngx_str_t                                  filter;
    ngx_uint_t                                 used;
    ngx_rbtree_node_t                         *node;
    ngx_http_vhost_traffic_status_ctx_t       *ctx;

    ctx = ngx_http_get_module_main_conf(r, ngx_http_vhost_traffic_status_module);
    node = NULL;

    /* disabled */
    if (ctx->filter_max_node == 0) {
        return NULL;
    }

    /*
     * The cap counts the nodes of the filter groups the directive names, so
     * only an insertion into one of those groups can take it over. A server
     * zone, an upstream peer, a cache or a filter of a group the directive
     * does not name has nothing to do with it, and dropping a node for one
     * of them loses a measurement while the zone still has room.
     */

    if (type != NGX_HTTP_VHOST_TRAFFIC_STATUS_UPSTREAM_FG) {
        return NULL;
    }

ngx_http_vhost_traffic_status_node_init(ngx_http_request_t *r,
    ngx_http_vhost_traffic_status_node_t *vtsn, ngx_int_t status_code_slot,
    ngx_http_upstream_state_t *state)
{
    ngx_msec_int_t  ms;

    /* init serverZone */
    ngx_http_vhost_traffic_status_node_zero(vtsn);
    ngx_http_vhost_traffic_status_node_time_queue_init(&vtsn->stat_request_times);
    ngx_http_vhost_traffic_status_node_histogram_bucket_init(r, &vtsn->stat_request_buckets);

    /* init upstreamZone */
    vtsn->stat_upstream.type = NGX_HTTP_VHOST_TRAFFIC_STATUS_UPSTREAM_NO;
    vtsn->stat_upstream.response_time_counter = 0;
    vtsn->stat_upstream.response_time = 0;
    ngx_http_vhost_traffic_status_node_time_queue_init(&vtsn->stat_upstream.response_times);
    ngx_http_vhost_traffic_status_node_histogram_bucket_init(r,
        &vtsn->stat_upstream.response_buckets);

    /* set serverZone */
    ms = ngx_http_vhost_traffic_status_request_time(r);

    ngx_http_vhost_traffic_status_node_update(r, vtsn, ms, status_code_slot, state);
}


/*
   Update the node from a subsequent request. Now there is more than one request,
   calculate the average request time.
*/
void
ngx_http_vhost_traffic_status_node_set(ngx_http_request_t *r,
    ngx_http_vhost_traffic_status_node_t *vtsn, ngx_int_t status_code_slot,
    ngx_http_upstream_state_t *state)
{
    ngx_msec_int_t                             ms;
    ngx_http_vhost_traffic_status_node_oc_t    ovtsn;
    ngx_http_vhost_traffic_status_loc_conf_t  *vtscf;

    vtscf = ngx_http_get_module_loc_conf(r, ngx_http_vhost_traffic_status_module);

    ngx_http_vhost_traffic_status_copy_oc((&ovtsn), vtsn);

    vtsn->ignore_status = vtscf->ignore_status;
    ms = ngx_http_vhost_traffic_status_request_time(r);
    ngx_http_vhost_traffic_status_node_update(r, vtsn, ms, status_code_slot, state);

    /*
     * stat_request_time is not kept up to date here: averaging the queue on
     * every request costs a loop over the whole queue while the shared memory
     * is locked. The readers compute it when they need it.
     */

    ngx_http_vhost_traffic_status_add_oc((&ovtsn), vtsn);
}

void
ngx_http_vhost_traffic_status_node_update(ngx_http_request_t *r,
    ngx_http_vhost_traffic_status_node_t *vtsn, ngx_msec_int_t ms, ngx_int_t status_code_slot,
    ngx_http_upstream_state_t *state)
{
    /*
     * state is the attempt this call is counting, and it is set only where
     * proxy_next_upstream passed that attempt on to another peer. Everything
     * else - every server, filter and cache zone, and the attempt that did
     * serve the client - counts the client request and leaves it NULL.
     */

    ngx_uint_t status = (state != NULL) ? state->status : r->headers_out.status;

    /*
     * Before the check below: a status that is not counted still leaves the
     * node reached - the client request was served, or the attempt on this
     * peer was made - and being reached is what tells it apart from one
     * nothing has used in a long time. Being counted is not.
     */

    vtsn->stat_last_seen = ngx_http_vhost_traffic_status_current_msec();

    if (ngx_http_vhost_traffic_status_ignore_status(vtsn->ignore_status, status)) {
        return;
    }

    vtsn->stat_request_counter++;

    if (state != NULL && (status < 100 || status >= 600)) {

        /*
         * An attempt carries no status of its own where it produced no
         * response, and nginx leaves that 0. add_rc() puts anything below 200
         * in the 1xx bucket, so it must not be handed one - the attempt would
         * be reported as an informational response. The two other places that
         * read this status already say the same thing: shm_add_node() takes no
         * status code slot outside 100..599, and the response time helper
         * gives 0 for a state with no status.
         *
         * It was still an attempt on this peer, so the counter above stands.
         */

        return;
    }

    ngx_http_vhost_traffic_status_add_rc(status, vtsn);

    if (status_code_slot != -1 && vtsn->stat_status_code_counter != NULL ) {
        vtsn->stat_status_code_counter[status_code_slot]++;
    }

    if (state != NULL) {

        /*
         * The rest of this describes the client request: the bytes either
         * way, how long it took, what the cache did with it. An attempt that
         * was passed on served no client, so it has none of them to add. Its
         * own response time goes to the upstream queue in
         * ngx_http_vhost_traffic_status_shm_add_node_upstream().
         */

        return;
    }

    vtsn->stat_in_bytes += (ngx_atomic_uint_t) r->request_length;
    vtsn->stat_out_bytes += (ngx_atomic_uint_t) r->connection->sent;

    vtsn->stat_request_time_counter += (ngx_atomic_uint_t) ms;

    ngx_http_vhost_traffic_status_node_time_queue_insert(&vtsn->stat_request_times,
                                                         ms);

    ngx_http_vhost_traffic_status_node_histogram_observe(&vtsn->stat_request_buckets,
                                                         ms);

#if (NGX_HTTP_CACHE)
    if (r->upstream != NULL && r->upstream->cache_status != 0) {
        ngx_http_vhost_traffic_status_add_cc(r->upstream->cache_status, vtsn);
    }
#endif
}

    /* set addition */
    switch(type) {
    case NGX_HTTP_VHOST_TRAFFIC_STATUS_UPSTREAM_NO:
        break;

    case NGX_HTTP_VHOST_TRAFFIC_STATUS_UPSTREAM_UA:
    case NGX_HTTP_VHOST_TRAFFIC_STATUS_UPSTREAM_UG:

        /*
         * Each attempt gets its own response time. The one that served the
         * client arrives here with state NULL, and r->upstream->state is the
         * last element of r->upstream_states, which is that same attempt.
         *
         * This used to be the sum over every attempt, given to whichever peer
         * answered, so a peer was charged for the time spent failing on the
         * peers before it.
         */

        ustate = (state != NULL) ? state
                 : (r->upstream != NULL ? r->upstream->state : NULL);

        ms = ngx_http_vhost_traffic_status_upstream_state_response_time(ustate);

        (void) ngx_http_vhost_traffic_status_shm_add_node_upstream(r, vtsn, init, ms);
        break;

#if (NGX_HTTP_CACHE)
    case NGX_HTTP_VHOST_TRAFFIC_STATUS_UPSTREAM_CC:
        (void) ngx_http_vhost_traffic_status_shm_add_node_cache(r, vtsn, init,
                   cache_max_size, cache_used_size);
        break;
#endif

    case NGX_HTTP_VHOST_TRAFFIC_STATUS_UPSTREAM_FG:
        break;
    }

    ngx_shmtx_unlock(&shpool->mutex);

    return NGX_OK;
}

if (format == NGX_HTTP_VHOST_TRAFFIC_STATUS_FORMAT_JSON) {
    shpool = (ngx_slab_pool_t *) vtscf->shm_zone->shm.addr;
    ngx_shmtx_lock(&shpool->mutex);
    b->last = ngx_http_vhost_traffic_status_display_set(r, b->last);
    ngx_shmtx_unlock(&shpool->mutex);

    if (b->last == b->pos) {
        b->last = ngx_sprintf(b->last, "{}");
    }

} else if (format == NGX_HTTP_VHOST_TRAFFIC_STATUS_FORMAT_JSONP) {
    shpool = (ngx_slab_pool_t *) vtscf->shm_zone->shm.addr;
    ngx_shmtx_lock(&shpool->mutex);
    b->last = ngx_sprintf(b->last, "%V", &vtscf->jsonp);
    b->last = ngx_sprintf(b->last, "(");
    b->last = ngx_http_vhost_traffic_status_display_set(r, b->last);
    b->last = ngx_sprintf(b->last, ")");
    ngx_shmtx_unlock(&shpool->mutex);

} else if (format == NGX_HTTP_VHOST_TRAFFIC_STATUS_FORMAT_PROMETHEUS) {
    shpool = (ngx_slab_pool_t *) vtscf->shm_zone->shm.addr;
    ngx_shmtx_lock(&shpool->mutex);
    b->last = ngx_http_vhost_traffic_status_display_prometheus_set(r, b->last);
    ngx_shmtx_unlock(&shpool->mutex);

    if (b->last == b->pos) {
        b->last = ngx_sprintf(b->last, "#");
    }

}

ngx_http_vhost_traffic_status_display_set(ngx_http_request_t *r,
    u_char *buf)
{
    u_char                                    *o, *s;
    ngx_rbtree_node_t                         *node;
    ngx_http_vhost_traffic_status_ctx_t       *ctx;
    ngx_http_vhost_traffic_status_loc_conf_t  *vtscf;

    ctx = ngx_http_get_module_main_conf(r, ngx_http_vhost_traffic_status_module);

    vtscf = ngx_http_get_module_loc_conf(r, ngx_http_vhost_traffic_status_module);

    node = ctx->rbtree->root;

    /* init stats */
    ngx_memzero(&vtscf->stats, sizeof(vtscf->stats));
    ngx_http_vhost_traffic_status_node_time_queue_init(&vtscf->stats.stat_request_times);

    if (ctx->measure_status_codes != NULL) {
        vtscf->stats.stat_status_code_counter = ngx_pcalloc(r->pool, sizeof(ngx_atomic_t) * (ctx->measure_status_codes->nelts +1));
        vtscf->stats.stat_status_code_length = ctx->measure_status_codes->nelts;
    }

    /* main & connections */
    buf = ngx_sprintf(buf, NGX_HTTP_VHOST_TRAFFIC_STATUS_JSON_FMT_S);

    buf = ngx_http_vhost_traffic_status_display_set_main(r, buf);

    /* serverZones */
    buf = ngx_sprintf(buf, NGX_HTTP_VHOST_TRAFFIC_STATUS_JSON_FMT_SERVER_S);

    buf = ngx_http_vhost_traffic_status_display_set_server(r, buf, node);

    buf = ngx_http_vhost_traffic_status_display_set_server_node(r, buf, &vtscf->sum_key,
                                                                &vtscf->stats);

u_char *
ngx_http_vhost_traffic_status_display_set_server(ngx_http_request_t *r,
    u_char *buf, ngx_rbtree_node_t *node)
{
    ngx_str_t                                  key;
    ngx_http_vhost_traffic_status_ctx_t       *ctx;
    ngx_http_vhost_traffic_status_node_t      *vtsn, ovtsn;
    ngx_http_vhost_traffic_status_loc_conf_t  *vtscf;

    ctx = ngx_http_get_module_main_conf(r, ngx_http_vhost_traffic_status_module);

    vtscf = ngx_http_get_module_loc_conf(r, ngx_http_vhost_traffic_status_module);

    if (node != ctx->rbtree->sentinel) {
        vtsn = (ngx_http_vhost_traffic_status_node_t *) &node->color;

        if (vtsn->stat_upstream.type == NGX_HTTP_VHOST_TRAFFIC_STATUS_UPSTREAM_NO) {
            key.data = vtsn->data;
            key.len = vtsn->len;

            ovtsn = vtscf->stats;

            buf = ngx_http_vhost_traffic_status_display_set_server_node(r, buf, &key, vtsn);

            /* calculates the sum */
            vtscf->stats.stat_request_counter += vtsn->stat_request_counter;
            vtscf->stats.stat_in_bytes += vtsn->stat_in_bytes;
            vtscf->stats.stat_out_bytes += vtsn->stat_out_bytes;
            vtscf->stats.stat_1xx_counter += vtsn->stat_1xx_counter;
            vtscf->stats.stat_2xx_counter += vtsn->stat_2xx_counter;
            vtscf->stats.stat_3xx_counter += vtsn->stat_3xx_counter;
            vtscf->stats.stat_4xx_counter += vtsn->stat_4xx_counter;
            vtscf->stats.stat_5xx_counter += vtsn->stat_5xx_counter;
            vtscf->stats.stat_request_time_counter += vtsn->stat_request_time_counter;

rc = ngx_http_vhost_traffic_status_escape_json_pool(r->pool, &dst, &tmp);
if (rc != NGX_OK) {
    ngx_log_error(NGX_LOG_ERR, r->connection->log, 0,
                  "display_set_server_node::escape_json_pool() failed");
}

if (ngx_http_vhost_traffic_status_display_buffer_check(r, buf, dst.len,
        NGX_HTTP_VHOST_TRAFFIC_STATUS_FORMAT_JSON) != NGX_OK)
{
    return buf;
}

buf = ngx_sprintf(buf, NGX_HTTP_VHOST_TRAFFIC_STATUS_JSON_FMT_SERVER_START,
    &dst, vtsn->stat_request_counter,
    vtsn->stat_in_bytes,
    vtsn->stat_out_bytes);

ngx_int_t
ngx_http_vhost_traffic_status_display_buffer_check(ngx_http_request_t *r,
    u_char *buf, size_t name_len, ngx_int_t format)
{
    size_t                                     need;
    ngx_http_vhost_traffic_status_loc_conf_t  *vtscf;

    vtscf = ngx_http_get_module_loc_conf(r, ngx_http_vhost_traffic_status_module);

    /* not called from a display handler */
    if (vtscf->display_buf_end == NULL) {
        return NGX_OK;
    }

    need = ngx_http_vhost_traffic_status_display_node_size(r, name_len, format);

    if (buf <= vtscf->display_buf_end
        && (size_t) (vtscf->display_buf_end - buf) >= need)
    {
        return NGX_OK;
    }

    ngx_log_error(NGX_LOG_ERR, r->connection->log, 0,
                  "display_buffer_check::not enough buffer: "
                  "left[%z], need[%uz], name[%uz], format[%i]",
                  (ssize_t) (vtscf->display_buf_end - buf), need, name_len,
                  format);

    return NGX_ERROR;
}

ngx_http_core_server(ngx_conf_t *cf, ngx_command_t *cmd, void *dummy)
{
    char                        *rv;
    void                        *mconf;
    size_t                       len;
    u_char                      *p;
    ngx_uint_t                   i;
    ngx_conf_t                   pcf;
    ngx_http_module_t           *module;
    struct sockaddr_in          *sin;
    ngx_http_conf_ctx_t         *ctx, *http_ctx;
    ngx_http_listen_opt_t        lsopt;
    ngx_http_core_srv_conf_t    *cscf, **cscfp;
    ngx_http_core_main_conf_t   *cmcf;

    ctx = ngx_pcalloc(cf->pool, sizeof(ngx_http_conf_ctx_t));
    if (ctx == NULL) {
        return NGX_CONF_ERROR;
    }

    http_ctx = cf->ctx;
    ctx->main_conf = http_ctx->main_conf;

    /* the server{}'s srv_conf */

    ctx->srv_conf = ngx_pcalloc(cf->pool, sizeof(void *) * ngx_http_max_module);
    if (ctx->srv_conf == NULL) {
        return NGX_CONF_ERROR;
    }

    /* the server{}'s loc_conf */

    ctx->loc_conf = ngx_pcalloc(cf->pool, sizeof(void *) * ngx_http_max_module);
    if (ctx->loc_conf == NULL) {
        return NGX_CONF_ERROR;
    }

    for (i = 0; cf->cycle->modules[i]; i++) {
        if (cf->cycle->modules[i]->type != NGX_HTTP_MODULE) {
            continue;
        }

        module = cf->cycle->modules[i]->ctx;

        if (module->create_srv_conf) {
            mconf = module->create_srv_conf(cf);
            if (mconf == NULL) {
                return NGX_CONF_ERROR;
            }

            ctx->srv_conf[cf->cycle->modules[i]->ctx_index] = mconf;
        }

        if (module->create_loc_conf) {
            mconf = module->create_loc_conf(cf);
            if (mconf == NULL) {
                return NGX_CONF_ERROR;
            }

            ctx->loc_conf[cf->cycle->modules[i]->ctx_index] = mconf;
        }
    }


    /* the server configuration context */

    cscf = ctx->srv_conf[ngx_http_core_module.ctx_index];
    cscf->ctx = ctx;


    cmcf = ctx->main_conf[ngx_http_core_module.ctx_index];

    cscfp = ngx_array_push(&cmcf->servers);
    if (cscfp == NULL) {
        return NGX_CONF_ERROR;
    }

    *cscfp = cscf;


    /* parse inside server{} */

    pcf = *cf;
    cf->ctx = ctx;
    cf->cmd_type = NGX_HTTP_SRV_CONF;

    rv = ngx_conf_parse(cf, NULL);

    *cf = pcf;

    if (rv == NGX_CONF_OK && !cscf->listen) {
        ngx_memzero(&lsopt, sizeof(ngx_http_listen_opt_t));

        p = ngx_pcalloc(cf->pool, sizeof(struct sockaddr_in));
        if (p == NULL) {
            return NGX_CONF_ERROR;
        }

        lsopt.sockaddr = (struct sockaddr *) p;

        sin = (struct sockaddr_in *) p;

        sin->sin_family = AF_INET;
#if (NGX_WIN32)
        sin->sin_port = htons(80);
#else
        sin->sin_port = htons((getuid() == 0) ? 80 : 8000);
#endif
        sin->sin_addr.s_addr = INADDR_ANY;

        lsopt.socklen = sizeof(struct sockaddr_in);

        lsopt.backlog = NGX_LISTEN_BACKLOG;
        lsopt.type = SOCK_STREAM;
        lsopt.rcvbuf = -1;
        lsopt.sndbuf = -1;
#if (NGX_HAVE_SETFIB)
        lsopt.setfib = -1;
#endif
#if (NGX_HAVE_TCP_FASTOPEN)
        lsopt.fastopen = -1;
#endif
        lsopt.wildcard = 1;

        len = NGX_INET_ADDRSTRLEN + sizeof(":65535") - 1;

        p = ngx_pnalloc(cf->pool, len);
        if (p == NULL) {
            return NGX_CONF_ERROR;
        }

        lsopt.addr_text.data = p;
        lsopt.addr_text.len = ngx_sock_ntop(lsopt.sockaddr, lsopt.socklen, p,
                                            len, 1);

        if (ngx_http_add_listen(cf, cscf, &lsopt) != NGX_OK) {
            return NGX_CONF_ERROR;
        }
    }

    return rv;
}

ctx = ngx_pcalloc(cf->pool, sizeof(ngx_http_conf_ctx_t));
if (ctx == NULL) {
    return NGX_CONF_ERROR;
}

http_ctx = cf->ctx;
ctx->main_conf = http_ctx->main_conf;

/* the server{}'s srv_conf */

